from fastapi import APIRouter, Depends, HTTPException
from kubernetes_asyncio import client

router = APIRouter(prefix="/k8s/namespaces")

@router.delete("/{namespace}/storage/pvcs/{pvc_name}")
async def delete_pvc(
    namespace: str,
    pvc_name: str,
    current_user: User = Depends(get_current_user),
    core_api: client.CoreV1Api = Depends(get_k8s_core_api)
):
    if namespace != current_user.tenant_namespace:
        raise HTTPException(status_code=403, detail="Forbidden: You cannot delete storage in other namespaces")

    try:
        status = await core_api.delete_namespaced_persistent_volume_claim(
            name=pvc_name,
            namespace=namespace
        )
    except client.exceptions.ApiException as e:
        raise HTTPException(status_code=e.status, detail=e.reason)

    return {
        "status": "deleted",
        "namespace": namespace,
        "pvc_name": pvc_name
    }
